"""Capability inventory with explicit gaps; a report, not a release gate."""
import argparse,json,pathlib,subprocess,tempfile
from test_runtime import ROOT,Server
from wire import *
parser=argparse.ArgumentParser();parser.add_argument('--skip-build',action='store_true',help='use the existing target/debug executable');a=parser.parse_args()
if not a.skip_build:subprocess.run(['cargo','build','--locked'],cwd=ROOT,check=True)
registry=json.loads((ROOT/'docs/specs/operations.json').read_text());versions={}
with tempfile.TemporaryDirectory(prefix='keytend-kmip-server-coverage-') as d:
    with Server(d,draft=True) as s:
        for name,ops in registry.items():
            v=tuple(map(int,name.split('.')))
            with s.connect() as c:
                p=payload(exchange(c,request(24,[enumeration(0x420074,1)],v)))
                advertised={n[2] for n in children(p,0x42005c)}
            versions[name]={'operation_count_in_spec':len(ops),'operation_handlers_advertised':len(advertised),'full_conformance_proven':False,'operations':[{'code':k,'name':n,'status':'partial' if int(k,16) in advertised else 'not_implemented'} for k,n in ops.items()]}
areas={
 'objects':{'partial':['Symmetric Key (AES and HMAC SHA-2)','RSA Public/Private Key','Weierstrass EC Public/Private Key','X.509 Certificate storage and bounded Validate with explicit trust/date/path policy','PGP Certificate Type 2 bounded public framing/metadata, transfer/reconstruction and schema-16 persistence','Password/Seed Secret Data','PGP v3/v4 Raw/Opaque containers, mandatory declared metadata and readonly multi-instance signature attributes from 1.2','vendor Opaque Object','Raw/Opaque Split Key transfer and bounded Create/Join with four methods, encrypted source provenance and new-object histories','2.0+ Certificate Request (PKCS#10/PEM Register, Get, Locate, Destroy; Certify/Re-certify by identifier)'],'missing':['Template objects','portable external opaque/nested Split Key representations and remaining formats/algorithms','PGP earlier-record metadata repair qualification, Key Value Location and metadata-only registration','PGP Certificate full grammar, trust, revocation and mechanism/profile qualification','Certificate Request CRMF, Import and splitting','3.0 groups/users/credentials']},
 'encodings':{'partial':['Binary TTLV over TLS','Profile JSON and XML with exact numeric/date/string mappings','HTTP/1.0 and HTTP/1.1 over mutual TLS; cross-encoding content negotiation and pre-commit response checks'],'missing':['external PKCS#11 symbolic enumeration tables','server-to-client HTTPS callback binding','complete transport/profile qualification']},
 'cryptography':{'partial':['AES ECB/CBC, CFB128, OFB, CTR and GCM','PKCS5 padding for ECB/CBC','GCM variable IVs and byte-valued tag lengths','stored cryptographic parameter selection and request override','HMAC SHA-256/384/512','RSA OAEP with distinct message/MGF digests and labels','RSA PSS/PKCS#1 v1.5 signatures','combined RSA signature identifiers and Digested Data','RSA PKCS#1 import and PKCS#8/SPKI conversions','68 Weierstrass named curves and EC transparent/PKCS#8/SEC1/SPKI transfer','ECDSA DER signatures and Digested Data with SHA-1/224/256/384/512','unkeyed SHA-1/224/256/384/512 and SHA-512/224/256 from 1.2; SHA-3 from 1.4','AES KW/KWP and RSA OAEP protected Get/Register/Import/Export','PBKDF2, HASH/HMAC/ENCRYPT, NIST counter/feedback/double-pipeline, HKDF and AWS Signature V4 derivation','OS/OpenSSL CSPRNG','RNG Seed from 1.2 that ignores client material and reports Data Length 0'],'optional_not_selected':['RNG Seed client-material ingestion; permitted ignore-and-zero policy selected'],'missing':['ECDH agreement, ECMQV, Edwards/Montgomery, DSA/DH','RSA PKCS#1 v1.5 encryption and other RSA mechanisms','SHA-3/legacy signature mechanisms','deployment mechanism allowlist policy','MAC/sign/composed/TR-31 and other wrapping variants','asymmetric derivation and alternate KDF combinations','complete Split Key factory/profile semantics','PQC/KEM','custom CTR field layouts','other algorithm/mechanism combinations']},
 'message_processing':{'partial':['ordered synchronous batches','Stop/Continue/Undo including protection output with retained usage debits','ID Placeholder','2.x/draft integer and operation-enumeration references','bounded multi-target expansion and response budget','response size rollback','version-specific synchronous indicators and error correlation','bounded principal-bound multipart AES/RSA/ECDSA/HMAC/Hash from 1.3; transactional context and allocation rollback'],'missing':['asynchronous operations','remaining multipart mechanisms and multi-process context failover','ephemeral operations','attestation','complete per-item error and placeholder semantics']},
 'attributes':{'partial':['multi-instance Name with server-global uniqueness and Re-key transfer','multi-instance Object Group','multi-instance Application Specific Information','Contact Information','Comment','Cryptographic Algorithm/Length/Usage Mask','X.509 subject algorithm/length versus issuer signature, certificate byte length, singleton legacy reads, immutable metadata and mandatory Register/Import validation','X.509 DER identifier/issuer/subject, repeated 2.x name fields, draft text DNs and schema-17 older-writer guard','PGP certificate primary key metadata, byte length and immutable repeated signature values with legacy indices','Cryptographic Parameters instances and indexed reads','legacy custom and 2.x vendor identity with structured references','stable encrypted instance indices and value-based 2.x mutations','identity-aware inheritance and missing-attribute responses','Re-key reciprocal history and persistent single-replacement guard','Re-key copied/offset lifecycle dates and independent material','RSA/EC Re-key Key Pair with atomic four-object history','EC Cryptographic Domain Parameters and compressed point export','Sensitive wrapped retrieval and non-extractable denial','wrapped attributes and 2.x/draft wrapping-key links','Import/Export of supplied metadata, usage remainder and original envelopes','common/key-specific multi-instance union and single-value precedence','State','Short Unique Identifier from 2.1','draft Object Class User and fourteen typed links','Digest','Key Format Type','initial/change/lifecycle dates with checked cross-date Add/Modify/Set and state/elapsed restrictions','2.0+ scalar Adjust Attribute with checked arithmetic, readonly policy and rollback','versioned Fresh and original creation date','RNG metadata and factory preference validation','Sensitive/Extractable defaults and monotone extraction histories','Software protection-storage selection, immutable encrypted metadata and Query masks from 2.0','mandatory restore fields, digest integrity and unique short IDs','material exposure history retained through Undo','Usage Limits and atomic lifetime protection accounting','server-controlled Lease Time and bounded Obtain Lease','Check count/mask/lease and Usage Limits Locate filters','Archive/Recover with persistent access policy and versioned Locate storage masks','Locate creation ordering, subset filters, typed exact/inclusive date ranges, undefined-date sentinel and ID placeholder','Check denial clears ID placeholder'],'missing':['remaining attributes','remaining object-specific multi-instance rules','URI names','full cross-version attribute projection','remaining Locate attribute/structural/Object Group Member filtering and complete date/profile qualification','all normative validation and error rules','Re-key Usage Limits table wording resolution']},
 'production':{'demonstrated':['five independent open-source clients','Percona database restart/backup/rotation/revocation','non-root container','certificate operation ACL intersected with exact owner/identifier read grants','separate Get, metadata and Locate permissions; controlled-restart revocation'],'not_proven':['full specification conformance','five qualified maintained production SDKs','independent security audit','availability/failover SLOs','Percona Server for MongoDB 8.0 capacity and supported production topology requirements','remote audit checkpoints and rollback detection','all certificate lifecycle/CRL rotation scenarios']},
 'draft_3_0':{'baseline':['CSD02 framing without Batch Count, Batch Order Option or item IDs','Identifier/Reference/NameReference UTF-8 types','TextString Names and typed links','3.0 Attributes','Ping','Deactivate'],'missing':['remaining 3.0 link/group/user/credential semantics','Encapsulate/Decapsulate','PQC profiles','full draft conformance']}
}
report={'versions':versions,'areas':areas}
out=ROOT/'artifacts';out.mkdir(exist_ok=True);(out/'coverage.json').write_text(json.dumps(report,indent=2)+'\n')
for name,v in versions.items():print(f'{name}: {v["operation_handlers_advertised"]}/{v["operation_count_in_spec"]} handlers, partial semantics; full conformance unproven')
